entries[133709] = { ["name"] = "Funky Sea Snail", ["text"] = "Unique\nCarrying the snail may attract drogbar.\nRequires Akule Riverhorn - Good Friend\n\"Despite its aquatic origins, the snail exudes a strong scent. Useful when fishing in Highmountain.\"\nSell Price:" }
