entries[133871] = { ["name"] = "Recipe: Crispy Bacon", ["text"] = "Rank 1\nBinds when picked up\nUse: Teaches you how to cook Crispy Bacon.\nPrepare Crispy Bacon.\nRequires Legion Cooking (1)\nSell Price:\nCrispy Bacon\nUse: Eat some bacon!\n\nExtend the benefit of any Well Fed buff from the Broken Isles by 1 hour, up to a maximum of 6 hours.\nSell Price:\nRequires Slice of Bacon (5), Dalapeño Pepper (5)" }
entries[133872] = { ["name"] = "Recipe: Crispy Bacon", ["text"] = "Rank 2\nBinds when picked up\nUse: Teaches you how to cook Crispy Bacon more efficiently.\nPrepare more Crispy Bacon in each batch.\nRequires Legion Cooking (1)\nSell Price:\nCrispy Bacon\nUse: Eat some bacon!\n\nExtend the benefit of any Well Fed buff from the Broken Isles by 1 hour, up to a maximum of 6 hours.\nSell Price:\nRequires Slice of Bacon (5), Dalapeño Pepper (5)" }
entries[133873] = { ["name"] = "Recipe: Crispy Bacon", ["text"] = "Rank 3\nBinds when picked up\nUse: Teaches you how to cook Crispy Bacon more efficiently.\nYou don't waste a single ingredient, preparing much more Crispy Bacon in each batch.\nRequires Legion Cooking (1)\nSell Price:\nCrispy Bacon\nUse: Eat some bacon!\n\nExtend the benefit of any Well Fed buff from the Broken Isles by 1 hour, up to a maximum of 6 hours.\nSell Price:\nRequires Slice of Bacon (5), Dalapeño Pepper (5)" }
