entries[133968] = { ["name"] = "Moon Guard Sigil", ["text"] = "Binds when picked up\nUnique\nThis Item Begins a Quest\n\"Bearers of this inscribed talisman have proven themselves exceptionally skilled sorcerers.\"" }
entries[133970] = { ["name"] = "Zann'esu Journey", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWaist Cloth\n3 Armor\n+4 Intellect\n+6 Stamina\n+ 3 Critical Strike\n+ 4 Haste\nDurability 70 / 70\nClasses: Mage\nEquip: Flurry increases the damage of your next Blizzard by 35%, stacking up to 5 times.\n\"The Zann'esu mage clan left their home village of Brunnhildar in search of the perfect magic to defeat the Lich King. They never returned.\"\nSell Price:" }
entries[133971] = { ["name"] = "Zenk'aram, Iridi's Anadem", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nHead Cloth\n4 Armor\n+5 Intellect\n+7 Stamina\n+ 6 Critical Strike\n+ 4 Haste\nDurability 120 / 120\nClasses: Priest\nEquip: Voidform increases your spell damage dealt by an additional 3% and increases your Vampiric Embrace healing by 250%.\n\"Constructed from the finest felcloth, Iridi drew power from this anadem to defeat Dargonax.\"\nSell Price:" }
entries[133972] = { ["name"] = "Basilisk Meat", ["text"] = "Quest Item\n\"This raw lizard meat is chewy and poisonous when uncooked.\"" }
entries[133973] = { ["name"] = "The Twins' Painful Touch", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 8 Critical Strike\n+ 6 Haste\n\nPrismatic Socket\n\nClasses: Priest\nEquip: Your first [ Mind Spike / Mind Flay] cast after entering Voidform spreads Shadow Word: Pain and Vampiric Touch to 3 enemies within 10 yards of your target.\n\"'Enough with these orbs, Fjola. Let's finish these challengers.' -Eydis Darkbane\"\nSell Price:" }
entries[133974] = { ["name"] = "Lana'thel's Lament", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+4 Stamina\n+ 9 Haste\n+ 5 Versatility\n\nPrismatic Socket\n\nClasses: Death Knight\nEquip: You deal 5% more damage and receive 5% more healing while standing in your Death and Decay.\n\"Lana'thel shed tears for the lives of the elven kin she expected to lose during their war march to Northrend. She had no idea at the time that she would be the cause of many more.\"\nSell Price:" }
entries[133975] = { ["name"] = "Gnopetto's Journal", ["text"] = "Quest Item\n\"The majority of the pages are smeared, but there are some parts that are still somehow legible.\"" }
entries[133976] = { ["name"] = "Cinidaria, the Symbiote", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nWaist Leather\n5 Armor\n+4 [Agility or Intellect]\n+6 Stamina\n+ 5 Critical Strike\n+ 3 Mastery\nDurability 70 / 70\nClasses: Rogue , Monk , Druid , Demon Hunter\nEquip: Your attacks cause an additional 30% damage to enemies above 90% health and heal you for 100% of the damage done.\n\"This demonic symbiote adapted to draw power from the thrill of combat, sometimes mimicking the actions of its host.\"\nSell Price:" }
entries[133977] = { ["name"] = "Belo'vir's Final Stand", ["text"] = "Binds when picked up\nUnique-Equipped: Legion Legendary (1)\nChest Cloth\n5 Armor\n+5 Intellect\n+7 Stamina\n+ 6 Critical Strike\n+ 4 Haste\n+ 3 Mastery\nDurability 200 / 200\nClasses: Mage\nEquip: After casting [ Shimmer / Blink], you gain an absorb shield equal to 20% of your maximum health for 15 sec.\n\"The final act of Belo'vir Salonar, grand magister of Quel'Thalas during the Third War, was to teleport Lady Liadrin to safety as the city fell.\"\nSell Price:" }
